// 24-S7 acceptance: the presence store against PostgreSQL, in a throwaway
// schema (`src/test-support/database.ts`). A tab's heartbeat makes its
// account present to the puzzle's other builders for 15 s, written at most
// about every 5 s; a hidden tab stays present for 5 minutes; a closing tab
// leaves. Each account is listed once, never to itself, and only while it
// can still edit the puzzle. Do not edit this file to match an
// implementation.
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { Prisma } from '@prisma/client';
import { createGrid } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import { createTestDatabase, type TestDatabase } from '@/test-support/database';
import { AWAY_WINDOW_MS, PRESENCE_WINDOW_MS, heartbeat, leave, markAway, presentBuilders } from './presence';

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
  await db.client.user.createMany({ data: [
    { id: 'adam', name: 'Adam', email: 'adam@presence.example.test', displayName: 'Adam' },
    { id: 'jay', name: 'Jay', email: 'jay@presence.example.test', displayName: 'Jay' },
    { id: 'kim', name: 'Kim', email: 'kim@presence.example.test', displayName: 'Kim' },
    { id: 'eve', name: 'Eve', email: 'eve@presence.example.test', displayName: 'Eve' },
  ] });
}, 60_000);
afterAll(async () => { await db?.drop(); });

const blank = serializeGrid(createGrid({ cols: 3, rows: 3 }));
/** Adam's puzzle, shared with Jay and Kim. */
async function seed() {
  const { id } = await db.client.puzzle.create({
    data: { builderId: 'adam', title: 'Presence', grid: blank as unknown as Prisma.InputJsonValue, hints: {} },
  });
  await db.client.puzzleCollaborator.createMany({ data: [{ puzzleId: id, userId: 'jay' }, { puzzleId: id, userId: 'kim' }] });
  return id;
}
const T0 = new Date('2026-11-14T10:00:00.000Z');
const at = (ms: number) => new Date(T0.getTime() + ms);
const ids = (builders: readonly { userId: string }[]) => builders.map((builder) => builder.userId);
async function expiry(puzzleId: string, clientId: string) {
  const row = await db.client.puzzlePresence.findUnique({ where: { puzzleId_clientId: { puzzleId, clientId } } });
  return row?.expiresAt.getTime() ?? null;
}

describe('24-S7-1 the presence store', () => {
  it('a heartbeat makes the tab present to the other builders, once per account, with its username', async () => {
    const id = await seed();
    expect(await presentBuilders(db.client, 'adam', id, T0)).toEqual([]);
    await heartbeat(db.client, 'jay', id, 'jay-tab-1', T0);
    await heartbeat(db.client, 'jay', id, 'jay-tab-2', T0);
    await heartbeat(db.client, 'adam', id, 'adam-tab', T0);
    expect(await presentBuilders(db.client, 'adam', id, at(1000))).toEqual([{ userId: 'jay', username: 'Jay' }]);
    expect(await presentBuilders(db.client, 'jay', id, at(1000))).toEqual([{ userId: 'adam', username: 'Adam' }]);
    await heartbeat(db.client, 'kim', id, 'kim-tab', T0);
    expect(ids(await presentBuilders(db.client, 'adam', id, at(1000)))).toEqual(['jay', 'kim']);
  });

  it('present until 15 s after the last write; a heartbeat with more than 10 s left writes nothing', async () => {
    const id = await seed();
    await heartbeat(db.client, 'jay', id, 'tab', T0);
    expect(await expiry(id, 'tab')).toBe(T0.getTime() + PRESENCE_WINDOW_MS);
    await heartbeat(db.client, 'jay', id, 'tab', at(3000));
    expect(await expiry(id, 'tab')).toBe(T0.getTime() + PRESENCE_WINDOW_MS);
    await heartbeat(db.client, 'jay', id, 'tab', at(6000));
    expect(await expiry(id, 'tab')).toBe(T0.getTime() + 6000 + PRESENCE_WINDOW_MS);
    expect(ids(await presentBuilders(db.client, 'adam', id, at(6000 + PRESENCE_WINDOW_MS - 1)))).toEqual(['jay']);
    expect(await presentBuilders(db.client, 'adam', id, at(6000 + PRESENCE_WINDOW_MS + 1))).toEqual([]);
  });

  it('away keeps the tab present for 5 minutes; leave removes only that tab; neither touches another account', async () => {
    const id = await seed();
    await heartbeat(db.client, 'jay', id, 'jay-tab', T0);
    await heartbeat(db.client, 'kim', id, 'kim-tab', T0);
    await markAway(db.client, 'jay', id, 'jay-tab', T0);
    expect(ids(await presentBuilders(db.client, 'adam', id, at(AWAY_WINDOW_MS - 1000)))).toEqual(['jay']);
    expect(await presentBuilders(db.client, 'adam', id, at(AWAY_WINDOW_MS + 1000))).toEqual([]);

    // Kim can't send Jay away or out.
    await heartbeat(db.client, 'jay', id, 'jay-tab', at(1000));
    const before = await expiry(id, 'jay-tab');
    await markAway(db.client, 'kim', id, 'jay-tab', at(1000));
    await leave(db.client, 'kim', id, 'jay-tab');
    expect(await expiry(id, 'jay-tab')).toBe(before);

    await heartbeat(db.client, 'jay', id, 'jay-other-tab', at(1000));
    await leave(db.client, 'jay', id, 'jay-tab');
    expect(await expiry(id, 'jay-tab')).toBeNull();
    expect(await expiry(id, 'jay-other-tab')).not.toBeNull();
    expect(await expiry(id, 'kim-tab')).not.toBeNull();
  });

  it('an account removed from the puzzle is not present, even with an unexpired row', async () => {
    const id = await seed();
    await heartbeat(db.client, 'jay', id, 'tab', T0);
    await db.client.puzzleCollaborator.delete({ where: { puzzleId_userId: { puzzleId: id, userId: 'jay' } } });
    expect(await presentBuilders(db.client, 'adam', id, at(1000))).toEqual([]);
    // Eve was never a builder of it.
    await db.client.puzzlePresence.create({ data: { puzzleId: id, clientId: 'eve-tab', userId: 'eve', expiresAt: at(60_000) } });
    expect(await presentBuilders(db.client, 'adam', id, at(1000))).toEqual([]);
  });

  it('rows expired over an hour ago are pruned when a tab’s row is created', async () => {
    const id = await seed();
    await db.client.puzzlePresence.createMany({ data: [
      { puzzleId: id, clientId: 'old', userId: 'kim', expiresAt: at(-2 * 3600_000) },
      { puzzleId: id, clientId: 'recent', userId: 'kim', expiresAt: at(-60_000) },
    ] });
    await heartbeat(db.client, 'jay', id, 'new-tab', T0);
    expect(await expiry(id, 'old')).toBeNull();
    expect(await expiry(id, 'recent')).not.toBeNull();
  });
});
